def eval_postfix(expr):
    stack = []
    for tok in expr.split():
        if tok.isdigit():
            stack.append(int(tok))
        else:
            b = stack.pop()          # right operand comes off first
            a = stack.pop()
            if tok == '+': stack.append(a + b)
            elif tok == '-': stack.append(a - b)
            elif tok == '*': stack.append(a * b)
            elif tok == '/': stack.append(a // b)
        print(tok, stack)
    return stack.pop()

print("Result:", eval_postfix("6 2 3 + - 3 8 2 / + *"))

#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

struct Node *push(struct Node *head, int x) {  /* insert at head: O(1) */
    struct Node *n = malloc(sizeof(struct Node));
    n->data = x;
    n->next = head;
    return n;
}

struct Node *reverse(struct Node *head) {       /* O(n) time, O(1) space */
    struct Node *prev = NULL, *next;
    while (head != NULL) {
        next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(struct Node *p) {
    while (p != NULL) {
        printf("%d -> ", p->data);
        p = p->next;
    }
    printf("NULL\n");
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 1; i <= 4; i++)
        head = push(head, i * 10);
    print(head);
    head = reverse(head);
    print(head);
    return 0;
}

#include <stdio.h>

int binarySearch(int a[], int n, int key, int *comparisons) {
    int low = 0, high = n - 1;
    *comparisons = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        (*comparisons)++;
        if (a[mid] == key) return mid;
        else if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;                     /* low > high: not found */
}

int main(void) {
    int a[] = {3, 8, 15, 23, 42, 57, 61, 79, 88, 94};
    int c;
    int pos = binarySearch(a, 10, 61, &c);
    printf("61 found at index %d after %d comparisons\n", pos, c);
    pos = binarySearch(a, 10, 50, &c);
    printf("50: result %d after %d comparisons\n", pos, c);
    return 0;
}

def bubble_passes(a):
    a, n = a[:], len(a)
    for p in range(n - 1):
        swapped = False
        for j in range(n - 1 - p):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        print("bubble pass", p + 1, a)
        if not swapped:
            break

def selection_passes(a):
    a = a[:]
    for i in range(len(a) - 1):
        m = min(range(i, len(a)), key=a.__getitem__)
        a[i], a[m] = a[m], a[i]
        print("selection pass", i + 1, a)

bubble_passes([5, 1, 4, 2, 8])
selection_passes([29, 10, 14, 37, 13])
